1	// Runtime engine discovery -- the hot-plug seam.
2	//
3	// discover_engines() returns the built-in qemu descriptor plus every engine
4	// found by scanning a directory and asking each binary to self-report via
5	// `--describe` (falling back to a <bin>.json sidecar). No engine is compiled
6	// into the framework; dropping a freshly built sim_<cfg> into the scan dir
7	// makes it appear here with no andesim rebuild.
8	//
9	// Scan dir: $ANDESIM_ENGINES_DIR (colon-separated; REPLACES the default and
10	// accepts any executable) if set, else vsim_scan_dir() (filtered to sim_*
11	// binaries) -- $VSIM_BIN_DIR, the external prebuilt vsim build dir mirroring
12	// $QEMU_BIN_DIR, falling back to the legacy in-tree <repo>/verilator/build.
13	#ifndef ANDESIM_ENGINE_REGISTRY_HPP
14	#define ANDESIM_ENGINE_REGISTRY_HPP
15	
16	#include <filesystem>
17	#include <string>
18	#include <vector>
19	
20	#include "engine_descriptor.hpp"
21	#include "strutil.hpp"
22	
23	namespace andes_sim {
24	
25	// Built-in functional engine ids (the qemu64/qemu32 pair). Declared once here so
26	// builtin_qemu_arch, the hybrid plan steps, and `run --mode fast` acceptance all
27	// agree -- a renamed literal would otherwise break find_engine() lookups only at
28	// run time.
29	inline constexpr const char* kQemuId64 = "qemu64";
30	inline constexpr const char* kQemuId32 = "qemu32";
31	
32	struct Discovery {
33	  std::vector<EngineDescriptor> engines;   // deduped by id; qemu first
34	  std::vector<std::string> warnings;       // binaries that failed to describe
35	};
36	
37	Discovery discover_engines();
38	
39	// Directory discover_engines() scans for sim_* engines when $ANDESIM_ENGINES_DIR
40	// is unset: VSIM_BIN_DIR (the external prebuilt vsim build, mirroring
41	// QEMU_BIN_DIR) resolved env-first then from config.env, else the legacy in-tree
42	// <repo>/verilator/build.
43	std::filesystem::path vsim_scan_dir();
44	
45	// The bundled qemu descriptor (no directory scan, no --describe subprocess).
46	// discover_engines() seeds the registry with it; `run --mode fast` resolves
47	// qemu through it directly, paying none of the Verilator-engine discovery cost.
48	// builtin_qemu_arch(xlen) builds the rv64 "qemu64" (xlen=64) or rv32 "qemu32"
49	// (xlen=32, qemu-system-riscv32); builtin_qemu() is the rv64 default.
50	EngineDescriptor builtin_qemu_arch(int xlen);
51	EngineDescriptor builtin_qemu();
52	
53	// Rewrite a discovered engine's identity from the third-party simulator name to
54	// the product name: type "verilator" -> "vsim", id "verilator:<cfg>" ->
55	// "vsim:<cfg>". discover_engines() applies this once, before the id is used for
56	// dedup or shown anywhere, so every downstream consumer (list / --engine /
57	// errors / run banner) speaks "vsim" and a user never sees "verilator". Any
58	// other backend (qemu, a drop-in alioth/sid) passes through untouched.
59	inline void normalize_engine_label(EngineDescriptor& d) {
60	  if (d.type == "verilator") d.type = "vsim";
61	  if (d.id.rfind("verilator:", 0) == 0) d.id = "vsim:" + d.id.substr(10);
62	}
63	
64	// Select the cycle-accurate engine for `run --mode cycle` from an
65	// already-discovered set (pure; spawns nothing). With `want_id` empty, default
66	// to the sole cycle-accurate engine -- erroring if there are none or more than
67	// one (ambiguous). With `want_id` set, that engine must exist and be
68	// cycle-accurate. Returns nullptr and sets `err` (naming the available
69	// cycle-accurate ids) on any failure; the returned pointer aliases into
70	// `engines`, so it must outlive the result.
71	inline const EngineDescriptor* resolve_accurate_engine(
72	    const std::vector<EngineDescriptor>& engines, const std::string& want_id,
73	    std::string& err) {
74	  auto is_accurate = [](const EngineDescriptor& e) {
75	    return e.kind == "cycle-accurate";
76	  };
77	  auto accurate_ids = [&] {
78	    std::vector<std::string> ids;
79	    for (const EngineDescriptor& e : engines)
80	      if (is_accurate(e)) ids.push_back(e.id);
81	    return join(ids, ", ");
82	  };
83	
84	  if (!want_id.empty()) {  // explicit --engine
85	    for (const EngineDescriptor& e : engines) {
86	      if (e.id != want_id) continue;
87	      if (is_accurate(e)) return &e;
88	      err = "engine '" + want_id + "' is " +
89	            (e.kind.empty() ? "not cycle-accurate" : e.kind) +
90	            "; model cycle needs a cycle-accurate engine";
91	      return nullptr;
92	    }
93	    std::string have = accurate_ids();
94	    err = "no engine '" + want_id + "'" +
95	          (have.empty() ? " (no cycle-accurate engines found)"
96	                        : " (cycle-accurate engines: " + have + ")");
97	    return nullptr;
98	  }
99	
100	  // No --engine: default to the sole cycle-accurate engine.
101	  const EngineDescriptor* sole = nullptr;
102	  int n = 0;
103	  for (const EngineDescriptor& e : engines)
104	    if (is_accurate(e)) { sole = &e; ++n; }
105	  if (n == 1) return sole;
106	  if (n == 0)
107	    err = "model cycle: no cycle-accurate engine found "
108	          "(build one with: scripts/build_all.sh vsim)";
109	  else
110	    err = "model cycle: multiple cycle-accurate engines; select one with "
111	          "--engine (have: " + accurate_ids() + ")";
112	  return nullptr;
113	}
114	
115	}  // namespace andes_sim
116	
117	#endif  // ANDESIM_ENGINE_REGISTRY_HPP
