1	#include "engine_registry.hpp"
2	
3	#include <algorithm>
4	#include <cstdlib>
5	#include <filesystem>
6	#include <fstream>
7	#include <set>
8	#include <sstream>
9	
10	#include <unistd.h>
11	
12	#include "config_env.hpp"
13	#include "json.hpp"
14	#include "process.hpp"
15	#include "repo_root.hpp"
16	
17	namespace fs = std::filesystem;
18	
19	namespace andes_sim {
20	
21	// The bundled functional engine(s). QEMU does not implement --describe, so the
22	// descriptor is built in. builtin_qemu_arch(64) is the rv64 "qemu64";
23	// builtin_qemu_arch(32) is the rv32 "qemu32" (qemu-system-riscv32). The
24	// standalone (model=fast) run uses qemu's OWN default -cpu -- the user's post-`--`
25	// args (incl. an explicit -cpu) still win; only the rv64 hybrid fast-leg pins a
26	// -cpu. Binary path honors $VSIM_QEMU / $VSIM_QEMU32, then $QEMU_BIN_DIR (env or
27	// config.env), then the legacy in-tree build. Exposed (engine_registry.hpp) so
28	// `run --mode fast` resolves qemu directly, skipping the per-engine --describe
29	// scan whole-registry discovery would spawn.
30	EngineDescriptor builtin_qemu_arch(int xlen) {
31	  const bool rv32 = (xlen == 32);
32	  EngineDescriptor d;
33	  d.id = rv32 ? kQemuId32 : kQemuId64;
34	  d.type = "qemu";
35	  d.kind = "functional";
36	  d.xlen = xlen;
37	  d.triggers = {"marker", "pc"};
38	  d.state = {"drain"};
39	  d.source = "built-in";
40	
41	  d.roles = {"standalone"};
42	  if (!rv32) {  // hybrid rv32 (qemu32 fast-leg + engine-matched -cpu) not wired yet
43	    // The hybrid fast-forward leg (rv64): load the ELF, drain on the plugin's
44	    // trigger into {state_out}, exit 200. {plugin}/{mmap}/{mmap_size}/{state_out}
45	    // are filled by the plan executor (F6); {trigger} is the plugin comma-suffix
46	    // (empty for marker), folded by leg_trigger_args (F9).
47	    d.roles.push_back("fast-leg");
48	    d.invoke.push_back(
49	        {"fast-leg",
50	         {"{bin}", "-object",
51	          "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
52	          "-machine", "andes_ae350,memory-backend=mem", "-cpu",
53	          "andes-ax45mpv,vlen={vlen}", "-nographic", "-semihosting-config",
54	          "enable=on,target=native", "-bios", "{elf}", "-plugin",
55	          "{plugin},outfile={state_out}{trigger}"}});
56	  }
57	
58	  // The standalone functional run (model=fast). andes_ae350's generic default
59	  // -cpu hangs the vplat fixtures, so pin the arch's andes vector core; the
60	  // user's post-`--` args (incl. a different -cpu) still win. run_passthrough
61	  // fills {bin}/{elf}.
62	  // rv32 -> andes-d23 (the project's rv32 vsim core, non-vector: no vlen).
63	  const char* fast_cpu = rv32 ? "andes-d23" : "andes-ax45mpv,vlen=512";
64	  d.invoke.push_back(
65	      {"standalone",
66	       {"{bin}", "-machine", "andes_ae350", "-cpu", fast_cpu, "-nographic",
67	        "-semihosting-config", "enable=on,target=native", "-bios", "{elf}"}});
68	
69	  const std::string sys =
70	      std::string("qemu-system-") + (rv32 ? "riscv32" : "riscv64");
71	  const char* env = rv32 ? "VSIM_QEMU32" : "VSIM_QEMU";
72	  if (const char* q = std::getenv(env); q && *q)
73	    d.bin_path = q;
74	  else if (std::string qd = config_env_value("QEMU_BIN_DIR"); !qd.empty())
75	    d.bin_path = (fs::path(qd) / sys).string();
76	  else
77	    d.bin_path = (repo_root() / "build" / "qemu" / sys).string();
78	  return d;
79	}
80	
81	// rv64 qemu (back-compat: the default functional engine and hybrid fast leg).
82	EngineDescriptor builtin_qemu() { return builtin_qemu_arch(64); }
83	
84	namespace {
85	
86	constexpr int kDescribeTimeoutMs = 5000;
87	
88	bool is_executable_file(const fs::path& p) {
89	  std::error_code ec;
90	  if (!fs::is_regular_file(p, ec)) return false;
91	  return ::access(p.c_str(), X_OK) == 0;
92	}
93	
94	std::string read_file(const fs::path& p) {
95	  std::ifstream f(p, std::ios::binary);
96	  std::ostringstream ss;
97	  ss << f.rdbuf();
98	  return ss.str();
99	}
100	
101	// Ask one binary to describe itself: try `<bin> --describe`, else read the
102	// <bin>.json sidecar. On success fills `d` and returns true; on failure leaves
103	// a human-readable note in `warn`.
104	bool describe_one(const fs::path& bin, EngineDescriptor& d, std::string& warn) {
105	  RunResult r = run_process({bin.string(), "--describe"}, kDescribeTimeoutMs);
106	  if (!r.spawn_failed && !r.timed_out && r.rc == 0) {
107	    json::Parsed p = json::parse(r.out);
108	    if (p.ok) {
109	      std::string err = descriptor_from_json(p.value, d);
