32	// $VSIM_PLUGIN else the in-repo default (matches the e2e harness / hsim).
33	std::string resolve_plugin(const std::string& override_path) {
34	  if (!override_path.empty()) return override_path;
35	  if (const char* p = std::getenv("VSIM_PLUGIN"); p && *p) return p;
36	  return default_plugin_path().string();
37	}
