40	
41	std::string plan_step_rc_error(size_t step, const Step& s, int expect_rc,
42	                               int got_rc) {
43	  std::string m = "plan step " + std::to_string(step) + ": expected exit " +
44	                  std::to_string(expect_rc) + ", got " + std::to_string(got_rc);
45	  // A drain step (expect_rc is the handoff/drain code) that exits 0 ran the ELF
46	  // to completion without ever hitting its ROI boundary -- the marker/pc
47	  // trigger never fired. This is THE common "unmarked ELF / wrong trigger"
48	  // mistake; name the kind so the fix is obvious, not a bare exit code.
49	  if (got_rc == 0 && expect_rc == kDrainRc)
50	    m += " -- the " + s.role + " ran to completion without reaching its " +
51	         s.trigger.kind +
52	         " trigger boundary (the ROI never drained; check the ELF actually "
53	         "reaches the " +
54	         s.trigger.kind + ")";
55	  return m;
56	}
57	
58	LegTriggerArgs leg_trigger_args(const Trigger& t, const std::string& role,
59	                                std::string& err) {
60	  err.clear();
61	  LegTriggerArgs out;
62	  if (t.kind == "marker") return out;  // markers detected by plugin/vsim, not argv
63	
64	  const bool fast = role == "fast-leg";
65	  const bool accurate = role == "accurate-leg";
66	  if (!fast && !accurate) return out;  // other roles carry no trigger args
67	
68	  // Required-param lookup. A missing key is a caller bug; surface it (don't
69	  // throw) so plan_argvs can report which step failed.
70	  auto param = [&](const char* key) -> const std::string* {
71	    auto it = t.params.find(key);
72	    if (it == t.params.end()) {
73	      err = "trigger '" + t.kind + "' missing param '" + key + "'";
74	      return nullptr;
75	    }
76	    return &it->second;
77	  };
78	
79	  if (t.kind == "pc") {
80	    if (fast) {
81	      if (const std::string* p = param("enter_pc"))
82	        out.plugin_suffix = ",enter_pc=" + *p;
83	    } else if (const std::string* p = param("exit_pc")) {
84	      out.extra = {"--hybrid-exit-pc", *p};
85	    }
86	    return out;
87	  }
88	
89	  // verify oracle leg (verify_oracle F4): a pure-QEMU drain at the ROI exit
90	  // boundary, sampling at vsim's actual halt pc (drain_pc -- the DMI halt
91	  // lands a few insns past the trigger, and the comparison is only valid at
92	  // the same architectural point). qemu-only: the oracle plan has no
93	  // accurate leg.
94	  if (t.kind == "verify-marker" || t.kind == "verify-pc") {
95	    if (!fast) return out;
96	    std::string suffix = ",exit_marker=1";
97	    if (t.kind == "verify-pc") {
98	      const std::string* p = param("exit_pc");
99	      if (!p) return out;
100	      suffix = ",exit_pc=" + *p;
101	    }
102	    if (const std::string* p = param("drain_pc"))
103	      out.plugin_suffix = suffix + ",drain_pc=" + *p;
104	    return out;
105	  }
106	
107	  err = "unknown trigger kind '" + t.kind + "'";
108	  return out;
109	}
110	
111	std::vector<std::vector<std::string>> plan_argvs(
112	    const Plan& plan, const std::vector<EngineDescriptor>& engines,
113	    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
114	  std::vector<std::vector<std::string>> out;
115	  out.reserve(plan.steps.size());
116	  std::string prev_state_out;  // empty for the cold first leg
117	
118	  // hw-config sync: {vlen} comes from the accurate-leg engine's descriptor.
119	  long vlen = 0;
120	  for (const Step& s : plan.steps)
121	    if (s.role == "accurate-leg")
122	      if (const EngineDescriptor* e = find_engine(engines, s.engine_id))
123	        if (e->vlen > 0) vlen = e->vlen;
124	  const std::string vlen_str = std::to_string(synced_vlen(vlen));
125	
126	  for (size_t i = 0; i < plan.steps.size(); ++i) {
127	    const Step& step = plan.steps[i];
128	    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
129	    if (!eng) {
