145	      return {};
146	    }
147	
148	    const std::string state_out = state_path(workdir, i);
149	    const std::map<std::string, std::string> m = {
150	        {"bin", eng->bin_path},
151	        {"elf", plan.elf},
152	        {"plugin", ctx.plugin_path},
153	        {"mmap", ctx.mmap_path},
154	        {"mmap_size", std::to_string(ctx.mem_size)},
155	        {"mmap_base", ctx.mmap_base},
