164	      return {};
165	    }
166	    // Trigger's vsim tokens, then user-forwarded per-leg flags -- both verbatim
167	    // after the filled template (matches tests/e2e.sh's ordering).
168	    argv.insert(argv.end(), lt.extra.begin(), lt.extra.end());
169	    argv.insert(argv.end(), step.extra_args.begin(), step.extra_args.end());
170	    out.push_back(std::move(argv));
171	    prev_state_out = state_out;
172	  }
173	  err.clear();
174	  return out;
175	}
