133	  // M-ext CSR block (v4): same gate (the engine's supported list now includes
134	  // the M-ext names) and the same HW-driven exclusion. A CSR the engine lacks
135	  // is neither restored, drained, nor compared.
136	  if (ref.flags & HYBRID_FLAG_M_EXT) {
137	#define X(field, addr, name)                                    \
138	  if (!andes_verify_excluded(name) && andes_supported_csr(name)) \
139	    cmp(r, name, ref.m_ext.field, got.m_ext.field);
140	    HYBRID_M_EXT_CSR_LIST(X)
141	#undef X
142	  }
143	
144	  return r;
145	}
