// `andesim list fixtures|models|engines`.
//
// `list fixtures` is a faithful C++ port of the Python hsim `parse_fixtures`
// + `list_fixtures`, so its output stays byte-identical to the golden driver
// (the parity flywheel depends on this). `list models` is new surface (the
// composition axis that replaced the old `--mode`). `list engines` is a
// scaffold until runtime discovery lands in F2.
#include <algorithm>
#include <cstdio>
#include <filesystem>
#include <fstream>
#include <set>
#include <sstream>
#include <string>
#include <vector>

#include "cli.hpp"
#include "dev_mode.hpp"
#include "engine_registry.hpp"
#include "models.hpp"
#include "repo_root.hpp"
#include "strutil.hpp"

namespace fs = std::filesystem;

namespace andes_sim {
namespace {

std::vector<std::string> read_lines(const fs::path& p, bool& ok) {
  std::ifstream f(p);
  std::vector<std::string> lines;
  ok = static_cast<bool>(f);
  if (!ok) return lines;
  std::string line;
  while (std::getline(f, line)) lines.push_back(line);
  return lines;
}

// Match a Makefile variable assignment at column 0: `VAR :?= <body>` where
// VAR is [A-Z_][A-Z0-9_]*. Mirrors the Python regex anchor. On success sets
// `var` and `body` (the text after `=`, continuation backslash included).
bool parse_assignment(const std::string& line, std::string& var,
                      std::string& body) {
  const size_t n = line.size();
  if (n == 0) return false;
  char c0 = line[0];
  if (!((c0 >= 'A' && c0 <= 'Z') || c0 == '_')) return false;
  size_t p = 0;
  while (p < n) {
    char c = line[p];
    if ((c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_') ++p;
    else break;
  }
  var = line.substr(0, p);
  while (p < n && (line[p] == ' ' || line[p] == '\t')) ++p;  // \s*
  if (p < n && line[p] == ':') ++p;                          // :?
  if (p >= n || line[p] != '=') return false;                // =
  ++p;
  body = line.substr(p);
  return true;
}

struct Fixture {
  std::string name;
  std::string family;
};

// Extract fixture (name, family) rows from tests/fixtures/Makefile in stable,
// family-grouped, file order; dedupe globally; append handoff_roundtrip last.
std::vector<Fixture> parse_fixtures(const std::vector<std::string>& lines) {
  static const std::pair<std::string, std::string> interesting[] = {
      {"RT_FIXTURES", "asm"},
      {"RT_C_FIXTURES", "c"},
      {"RT_C_V_FIXTURES", "c+rvv"},
      {"PROBE_V_FIXTURES", "probe"},
  };
  std::vector<Fixture> rows;
  std::set<std::string> seen;

  for (size_t k = 0; k < lines.size(); ++k) {
    std::string var, body;
    if (!parse_assignment(lines[k], var, body)) continue;
    std::string family;
    for (const auto& it : interesting)
      if (it.first == var) { family = it.second; break; }
    if (family.empty()) continue;

    // Splice continuation lines: a trailing backslash + newline becomes a space.
    size_t li = k;
    while (!body.empty() && body.back() == '\\') {
      body.pop_back();
      body.push_back(' ');
      if (++li < lines.size()) body += lines[li];
      else break;
    }

    std::istringstream iss(body);
    std::string name;
    while (iss >> name)
      if (seen.insert(name).second) rows.push_back({name, family});
  }

  // handoff_roundtrip is not in a *_FIXTURES var; list it explicitly.
  if (seen.insert("handoff_roundtrip").second)
    rows.push_back({"handoff_roundtrip", "asm"});

  return rows;
}

int list_fixtures() {
  fs::path mk = repo_root() / "tests" / "fixtures" / "Makefile";
  bool ok;
  std::vector<std::string> lines = read_lines(mk, ok);
  if (!ok) {
    std::fprintf(stderr, "andesim: missing %s\n", mk.c_str());
    return 2;
  }
  std::vector<Fixture> rows = parse_fixtures(lines);

  size_t width = 0;
  for (const Fixture& r : rows) width = std::max(width, r.name.size());

  std::printf("%s  FAMILY\n", ljust("FIXTURE", width).c_str());
  for (const Fixture& r : rows)
    std::printf("%s  %s\n", ljust(r.name, width).c_str(), r.family.c_str());
  return 0;
}

int list_models() {
  size_t wn = 5, we = 7;  // header widths: MODEL, ENGINES
  for (const Model& m : kModels) {
    wn = std::max(wn, m.name.size());
    we = std::max(we, m.engines.size());
  }
  std::printf("%s  %s  NOTES\n", ljust("MODEL", wn).c_str(),
              ljust("ENGINES", we).c_str());
  for (const Model& m : kModels)
    std::printf("%s  %s  %s\n", ljust(std::string(m.name), wn).c_str(),
                ljust(std::string(m.engines), we).c_str(),
                std::string(m.notes).c_str());
  return 0;
}

int list_engines() {
  Discovery disc = discover_engines();

  // Columns describe engine identity only. Triggers are a hybrid-MODEL option
  // (see `list models` / `run --help`), not an engine attribute, so no TRIGGERS
  // column here.
  size_t we = 6, wt = 4, wk = 4;  // ENGINE, TYPE, KIND headers
  for (const EngineDescriptor& e : disc.engines) {
    we = std::max(we, e.id.size());
    wt = std::max(wt, e.type.size());
    wk = std::max(wk, e.kind.size());
  }

  // Hardware params from each engine's --describe; "-" = not reported.
  std::printf("%s  %s  %s  XLEN  VLEN  DLEN  ELEN\n",
              ljust("ENGINE", we).c_str(), ljust("TYPE", wt).c_str(),
              ljust("KIND", wk).c_str());
  for (const EngineDescriptor& e : disc.engines)
    std::printf("%s  %s  %s  %-4s  %-4s  %-4s  %-4s\n", ljust(e.id, we).c_str(),
                ljust(e.type, wt).c_str(), ljust(e.kind, wk).c_str(),
                vlen_str(e.xlen).c_str(), vlen_str(e.vlen).c_str(),
                vlen_str(e.dlen).c_str(), vlen_str(e.elen).c_str());

  // Binaries that could not self-describe are reported, never silently dropped.
  for (const std::string& w : disc.warnings)
    std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
  return 0;
}

}  // namespace

int cmd_list(const Cli& cli) {
  // `fixtures` lists internal test ELFs -- a developer target, gated behind
  // ANDESIM_DEV so the release product offers only user-facing models/engines.
  const char* targets = is_dev_mode() ? "fixtures|models|engines" : "models|engines";
  if (cli.positional.empty()) {
    std::fprintf(stderr, "andesim list: expected one of %s\n", targets);
    return 2;
  }
  const std::string& t = cli.positional[0];
  if (t == "fixtures" && is_dev_mode()) return list_fixtures();
  if (t == "models") return list_models();
  if (t == "engines") return list_engines();
  std::fprintf(stderr, "andesim list: unknown target '%s' (want %s)\n",
               t.c_str(), targets);
  return 2;
}

}  // namespace andes_sim

// The phase-plan grammar driven by run_plan (F6) -- the C++ analog of
// orchestrator/plan.py's Session/Step model, minus the dropped QEMU2 step.
//
// A Plan is a list of Steps; each Step names an engine (by id, resolved against
// the F2 registry), the role to invoke it in (its `invoke` template key, e.g.
// "fast-leg" / "accurate-leg"), and a Trigger. run_plan spawns each leg in
// order, threads the drained hybrid_state_v1 file forward, and returns each
// leg's mcycle/minstret. Under the no-QEMU2-handback design every F6 step
// drains, so the hybrid cycle figure is the vsim-leg mcycle minus the qemu-leg
// mcycle.
#ifndef ANDESIM_PLAN_HPP
#define ANDESIM_PLAN_HPP

#include <map>
#include <string>
#include <vector>

#include "hybrid/state_abi.h"

namespace andes_sim {

// The ROI delimiter for a step. `kind` is marker|pc; `params` carries
// kind-specific values (e.g. enter_pc, exit_pc) that F9 maps onto trigger
// args. F6 only exercises the default marker case (no params).
struct Trigger {
  std::string kind;
  std::map<std::string, std::string> params;
};

// One leg of a plan: which engine, which invoke role, under which trigger.
// `extra_args` are verbatim tokens appended after the filled template and the
// trigger args -- the seam for user-forwarded per-leg flags (e.g. the vsim
// leg's --kanata), which are orthogonal to the trigger.
struct Step {
  std::string engine_id;  // "qemu" | "verilator:ax45mpv_premium"
  std::string role;       // invoke-template key: "fast-leg" | "accurate-leg"
  Trigger trigger;
  std::vector<std::string> extra_args{};  // default-init: keeps 3-field Step{} literals warning-free
};

// A whole hybrid run. Every step loads `elf`; the shared mmap (`mem_size`
// bytes, at `mmap_path` or allocated by run_plan when empty) survives across
// every leg so memory threads through.
struct Plan {
  std::string elf;          // path to the ELF every leg launches
  long long mem_size = 0;   // shared-mmap size in bytes
  std::string mmap_path;    // "" => run_plan allocates one (F5) and owns it
  std::vector<Step> steps;
};

// What one drain step measured (read back from its state file), plus the
// leg's captured stdout -- the guest program's own output (UART/semihosting)
// rides the engine's stdout and must flow through to the user. `st` is the
// full drained record (verify_oracle F4: run --verify diffs the vsim drain
// against the oracle leg's in-process, after run_plan removed the files).
struct PhaseResult {
  unsigned long long mcycle = 0;
  unsigned long long minstret = 0;
  std::string out;
  hybrid_state_v1 st{};
};

// Aggregate outcome. `error` empty => every step matched its expected exit and
// drained a valid state file; `phases` then holds one entry per step in order.
struct PlanResult {
  std::string error;
  std::vector<PhaseResult> phases;
  bool ok() const { return error.empty(); }
};

}  // namespace andes_sim

#endif  // ANDESIM_PLAN_HPP

// The pure core of `run --mode hybrid`: turn the CLI selection into a Trigger.
//
// Split out from cmd_run.cpp so it is unit-testable without spawning qemu/vsim.
// pc-mode boundaries are resolved against the ELF .symtab here (via elf_syms),
// so the live path in cmd_run only has to build the 2-step plan and run it.
#ifndef ANDESIM_HYBRID_HPP
#define ANDESIM_HYBRID_HPP

#include <string>
#include <vector>

#include "cli.hpp"
#include "engine_descriptor.hpp"
#include "plan.hpp"

namespace andes_sim {

// Build the ROI Trigger for a hybrid run from `cli` + `elf` (the ELF is needed
// to resolve pc-mode symbol boundaries). The pc boundaries are stored as
// "0x"-prefixed hex in params (enter_pc/exit_pc). On a missing/unresolvable pc
// boundary or unknown trigger, returns a Trigger with empty kind and sets `err`.
Trigger hybrid_trigger(const Cli& cli, const std::string& elf, std::string& err);

// Build the vsim accurate-leg's user-forwarded extra args (verbatim tokens
// appended after the trigger args): kanata ROI visualization
// (`--kanata <f> --kanata-roi [--objdump <f>]`). `kind` is the trigger kind,
// used to validate: --kanata is marker/pc only; --objdump requires --kanata.
// On a violation returns {} and sets `err`. Absent kanata yields an empty
// list (the common case).
std::vector<std::string> vsim_extra_args(const Cli& cli, const std::string& kind,
                                         std::string& err);

// ISA-sync guard for the accurate-leg engine: the hybrid fast leg is a 64-bit
// QEMU, so an engine reporting xlen != 64 cannot share architectural state
// with it. Returns "" when the pairing is valid, else the diagnostic. An
// engine that reports no xlen (0) is accepted as-is.
std::string hybrid_hw_check(const EngineDescriptor& acc);

}  // namespace andes_sim

#endif  // ANDESIM_HYBRID_HPP

